  1→use crate::compiler::CompiledModel;
  2→use crate::errors::CliError;
  3→use anyhow::Result;
  4→use smelt_backend::{
  5→    Backend, ExecutionResult, IncrementalStrategy, Materialization, MaterializationStrategy,
  6→    PartitionSpec,
  7→};
  8→use smelt_core::SourcesConfig;
  9→
 10→/// Execute a compiled model using any Backend implementation.
 11→pub async fn execute_model(
 12→    backend: &dyn Backend,
 13→    compiled: &CompiledModel,
 14→    schema: &str,
 15→    show_results: bool,
 16→) -> Result<ExecutionResult> {
 17→    // Convert CLI Materialization to Backend Materialization
 18→    let materialization = match compiled.materialization {
 19→        crate::config::Materialization::Table => Materialization::Table,
 20→        crate::config::Materialization::View => Materialization::View,
 21→    };
 22→
 23→    backend
 24→        .execute_model(
 25→            schema,
 26→            &compiled.name,
 27→            &compiled.sql,
 28→            materialization,
 29→            show_results,
 30→        )
 31→        .await
 32→        .map_err(|e| {
 33→            CliError::ExecutionError {
 34→                model: compiled.name.clone(),
 35→                sql: compiled.sql.clone(),
 36→                source: e.into(),
 37→            }
 38→            .into()
 39→        })
 40→}
 41→
 42→/// Execute a compiled model incrementally using the resolved strategy.
 43→///
 44→/// This function:
 45→/// 1. Applies the strategy (DELETE+INSERT, MERGE, APPEND, or INSERT OVERWRITE)
 46→/// 2. Auto-creates the table on first run if it doesn't exist
 47→pub async fn execute_model_incremental(
 48→    backend: &dyn Backend,
 49→    compiled: &CompiledModel,
 50→    schema: &str,
 51→    partition: PartitionSpec,
 52→    inc_strategy: IncrementalStrategy,
 53→    unique_key: Vec<String>,
 54→    show_results: bool,
 55→) -> Result<ExecutionResult> {
 56→    // Views can't be incremental - warn and use full refresh
 57→    if matches!(
 58→        compiled.materialization,
 59→        crate::config::Materialization::View
 60→    ) {
 61→        eprintln!(
 62→            "  Warning: {} is a view, using full refresh (views cannot be incremental)",
 63→            compiled.name
 64→        );
 65→        return execute_model(backend, compiled, schema, show_results).await;
 66→    }
 67→
 68→    let strategy = MaterializationStrategy::Incremental {
 69→        partition,
 70→        strategy: inc_strategy,
 71→        unique_key,
 72→    };
 73→
 74→    backend
 75→        .execute_model_incremental(
 76→            schema,
 77→            &compiled.name,
 78→            &compiled.sql,
 79→            Materialization::Table,
 80→            strategy,
 81→            show_results,
 82→        )
 83→        .await
 84→        .map_err(|e| {
 85→            CliError::ExecutionError {
 86→                model: compiled.name.clone(),
 87→                sql: compiled.sql.clone(),
 88→                source: e.into(),
 89→            }
 90→            .into()
 91→        })
 92→}
 93→
 94→/// Execute a multi-step plan (e.g., from cube split optimization).
 95→///
 96→/// Iterates through execution steps, creating temp tables, running the final
 97→/// query to produce the model output, and cleaning up temp tables.
 98→pub async fn execute_plan(
 99→    backend: &dyn Backend,
100→    model_name: &str,
101→    steps: &[smelt_optimizer::ExecutionStep],
102→    schema: &str,
103→    show_results: bool,
104→) -> Result<ExecutionResult> {
105→    let start = std::time::Instant::now();
106→
107→    for step in steps {
108→        match step {
109→            smelt_optimizer::ExecutionStep::CreateTemp { name, sql } => {
110→                let create_sql = format!("CREATE TEMP TABLE {} AS {}", name, sql);
111→                backend
112→                    .execute_sql(&create_sql)
113→                    .await
114→                    .map_err(|e| CliError::ExecutionError {
115→                        model: model_name.to_string(),
116→                        sql: create_sql.clone(),
117→                        source: e.into(),
118→                    })?;
119→            }
120→            smelt_optimizer::ExecutionStep::AppendToTemp { name, sql } => {
121→                let insert_sql = format!("INSERT INTO {} {}", name, sql);
122→                backend
123→                    .execute_sql(&insert_sql)
124→                    .await
125→                    .map_err(|e| CliError::ExecutionError {
126→                        model: model_name.to_string(),
127→                        sql: insert_sql.clone(),
128→                        source: e.into(),
129→                    })?;
130→            }
131→            smelt_optimizer::ExecutionStep::FinalQuery { sql } => {
132→                backend
133→                    .drop_table_if_exists(schema, model_name)
134→                    .await
135→                    .map_err(|e| CliError::ExecutionError {
136→                        model: model_name.to_string(),
137→                        sql: "DROP TABLE".to_string(),
138→                        source: e.into(),
139→                    })?;
140→                backend
141→                    .create_table_as(schema, model_name, sql)
142→                    .await
143→                    .map_err(|e| CliError::ExecutionError {
144→                        model: model_name.to_string(),
145→                        sql: sql.clone(),
146→                        source: e.into(),
147→                    })?;
148→            }
149→            smelt_optimizer::ExecutionStep::DropTemp { name } => {
150→                let drop_sql = format!("DROP TABLE IF EXISTS {}", name);
151→                // Best-effort cleanup — don't fail the whole plan if drop fails
152→                let _ = backend.execute_sql(&drop_sql).await;
153→            }
154→        }
155→    }
156→
157→    let duration = start.elapsed();
158→    let row_count = backend.get_row_count(schema, model_name).await.unwrap_or(0);
159→
160→    let preview = if show_results {
161→        backend.get_preview(schema, model_name, 10).await.ok()
162→    } else {
163→        None
164→    };
165→
166→    Ok(ExecutionResult {
167→        model_name: model_name.to_string(),
168→        duration,
169→        row_count,
170→        preview,
171→    })
172→}
173→
174→/// Execute a multi-step plan incrementally (cube split + incremental).
175→///
176→/// Applies time filtering to each step's SQL before execution, and uses
177→/// the resolved strategy for the final table update.
178→#[allow(clippy::too_many_arguments)]
179→pub async fn execute_plan_incremental(
180→    backend: &dyn Backend,
181→    model_name: &str,
182→    steps: &[smelt_optimizer::ExecutionStep],
183→    schema: &str,
184→    partition: PartitionSpec,
185→    event_time_column: &str,
186→    time_range: &crate::transformer::TimeRange,
187→    inc_strategy: IncrementalStrategy,
188→    unique_key: Vec<String>,
189→    show_results: bool,
190→) -> Result<ExecutionResult> {
191→    use crate::transformer::inject_time_filter;
192→
193→    let start = std::time::Instant::now();
194→
195→    let table_exists = backend
196→        .table_exists(schema, model_name)
197→        .await
198→        .unwrap_or(false);
199→
200→    // For DELETE+INSERT strategy, delete partitions upfront before inserting
201→    if table_exists && inc_strategy == IncrementalStrategy::DeleteInsert {
202→        backend
203→            .delete_partitions(schema, model_name, &partition)
204→            .await
205→            .map_err(|e| CliError::ExecutionError {
206→                model: model_name.to_string(),
207→                sql: "DELETE partitions".to_string(),
208→                source: e.into(),
209→            })?;
210→    }
211→
212→    for step in steps {
213→        match step {
214→            smelt_optimizer::ExecutionStep::CreateTemp { name, sql } => {
215→                let filtered_sql = inject_time_filter(sql, event_time_column, time_range)
216→                    .map_err(|e| anyhow::anyhow!("Failed to inject time filter: {}", e))?;
217→                let create_sql = format!("CREATE TEMP TABLE {} AS {}", name, filtered_sql);
218→                backend
219→                    .execute_sql(&create_sql)
220→                    .await
221→                    .map_err(|e| CliError::ExecutionError {
222→                        model: model_name.to_string(),
223→                        sql: create_sql.clone(),
224→                        source: e.into(),
225→                    })?;
226→            }
227→            smelt_optimizer::ExecutionStep::AppendToTemp { name, sql } => {
228→                let filtered_sql = inject_time_filter(sql, event_time_column, time_range)
229→                    .map_err(|e| anyhow::anyhow!("Failed to inject time filter: {}", e))?;
230→                let insert_sql = format!("INSERT INTO {} {}", name, filtered_sql);
231→                backend
232→                    .execute_sql(&insert_sql)
233→                    .await
234→                    .map_err(|e| CliError::ExecutionError {
235→                        model: model_name.to_string(),
236→                        sql: insert_sql.clone(),
237→                        source: e.into(),
238→                    })?;
239→            }
240→            smelt_optimizer::ExecutionStep::FinalQuery { sql } => {
241→                if !table_exists {
242→                    backend
243→                        .create_table_as(schema, model_name, sql)
244→                        .await
245→                        .map_err(|e| CliError::ExecutionError {
246→                            model: model_name.to_string(),
247→                            sql: sql.clone(),
248→                            source: e.into(),
249→                        })?;
250→                } else {
251→                    match inc_strategy {
252→                        IncrementalStrategy::DeleteInsert => {
253→                            // Partitions already deleted above
254→                            backend
255→                                .insert_into_from_query(schema, model_name, sql)
256→                                .await
257→                                .map_err(|e| CliError::ExecutionError {
258→                                    model: model_name.to_string(),
259→                                    sql: sql.clone(),
260→                                    source: e.into(),
261→                                })?;
262→                        }
263→                        IncrementalStrategy::Merge => {
264→                            backend
265→                                .merge_into(schema, model_name, sql, &unique_key)
266→                                .await
267→                                .map_err(|e| CliError::ExecutionError {
268→                                    model: model_name.to_string(),
269→                                    sql: sql.clone(),
270→                                    source: e.into(),
271→                                })?;
272→                        }
273→                        IncrementalStrategy::Append => {
274→                            backend
275→                                .insert_into_from_query(schema, model_name, sql)
276→                                .await
277→                                .map_err(|e| CliError::ExecutionError {
278→                                    model: model_name.to_string(),
279→                                    sql: sql.clone(),
280→                                    source: e.into(),
281→                                })?;
282→                        }
283→                        IncrementalStrategy::InsertOverwrite => {
284→                            backend
285→                                .insert_overwrite(schema, model_name, sql, &partition)
286→                                .await
287→                                .map_err(|e| CliError::ExecutionError {
288→                                    model: model_name.to_string(),
289→                                    sql: sql.clone(),
290→                                    source: e.into(),
291→                                })?;
292→                        }
293→                    }
294→                }
295→            }
296→            smelt_optimizer::ExecutionStep::DropTemp { name } => {
297→                let drop_sql = format!("DROP TABLE IF EXISTS {}", name);
298→                let _ = backend.execute_sql(&drop_sql).await;
299→            }
300→        }
301→    }
302→
303→    let duration = start.elapsed();
304→    let row_count = backend.get_row_count(schema, model_name).await.unwrap_or(0);
305→
306→    let preview = if show_results {
307→        backend.get_preview(schema, model_name, 10).await.ok()
308→    } else {
309→        None
310→    };
311→
312→    Ok(ExecutionResult {
313→        model_name: model_name.to_string(),
314→        duration,
315→        row_count,
316→        preview,
317→    })
318→}
