320→/// Validate that all source tables exist in the backend.
321→pub async fn validate_sources(backend: &dyn Backend, sources: &SourcesConfig) -> Result<()> {
322→    let mut missing = Vec::new();
323→
324→    for source in &sources.sources {
325→        for table in &source.tables {
326→            let exists = backend
327→                .table_exists(&source.name, &table.name)
328→                .await
329→                .unwrap_or(false);
330→
331→            if !exists {
332→                missing.push(format!("{}.{}", source.name, table.name));
333→            }
334→        }
335→    }
336→
337→    if !missing.is_empty() {
338→        return Err(CliError::SourceTablesNotFound { missing }.into());
339→    }
340→
341→    Ok(())
342→}
