  4→//! enabling multi-backend support (DuckDB, Spark, etc.).
  5→
  6→mod error;
  7→mod types;
  8→
  9→pub use error::BackendError;
 10→pub use smelt_core::config::{
 11→    Granularity, IncrementalConfig, IncrementalSafetyOverrides, IncrementalStrategy,
 12→};
 13→pub use smelt_dialect::{BackendCapabilities, SqlDialect};
 14→pub use types::{ExecutionResult, Materialization, MaterializationStrategy, PartitionSpec};
 15→
 16→use arrow::array::RecordBatch;
 17→use async_trait::async_trait;
 18→
 19→/// Abstract interface for smelt execution backends.
 20→///
 21→/// Backends are responsible for:
 22→/// - Executing SQL queries
 23→/// - Creating tables and views
 24→/// - Validating source tables exist
 25→/// - Reporting their SQL dialect and capabilities
 26→#[async_trait]
 27→pub trait Backend: Send + Sync {
 28→    /// Execute a SQL query and return results.
 29→    async fn execute_sql(&self, sql: &str) -> Result<Vec<RecordBatch>, BackendError>;
 30→
 31→    /// Create a table from a SQL query.
 32→    async fn create_table_as(
 33→        &self,
 34→        schema: &str,
 35→        name: &str,
 36→        sql: &str,
 37→    ) -> Result<(), BackendError>;
 38→
 39→    /// Create a view from a SQL query.
 40→    async fn create_view_as(&self, schema: &str, name: &str, sql: &str)
 41→        -> Result<(), BackendError>;
 42→
 43→    /// Drop a table if it exists.
 44→    async fn drop_table_if_exists(&self, schema: &str, name: &str) -> Result<(), BackendError>;
 45→
 46→    /// Drop a view if it exists.
 47→    async fn drop_view_if_exists(&self, schema: &str, name: &str) -> Result<(), BackendError>;
 48→
 49→    /// Get the row count of a table or view.
 50→    async fn get_row_count(&self, schema: &str, name: &str) -> Result<usize, BackendError>;
 51→
 52→    /// Get a preview of a table or view (first N rows).
 53→    async fn get_preview(
 54→        &self,
 55→        schema: &str,
 56→        name: &str,
 57→        limit: usize,
 58→    ) -> Result<Vec<RecordBatch>, BackendError>;
 59→
 60→    /// Check if a table exists.
 61→    async fn table_exists(&self, schema: &str, name: &str) -> Result<bool, BackendError>;
 62→
 63→    /// Ensure a schema exists, creating it if necessary.
 64→    async fn ensure_schema(&self, schema: &str) -> Result<(), BackendError>;
 65→
 66→    /// Get the SQL dialect this backend uses.
 67→    fn dialect(&self) -> SqlDialect;
 68→
 69→    /// Get the capabilities of this backend.
 70→    fn capabilities(&self) -> BackendCapabilities;
 71→
 72→    /// Execute a model (drop + create as table or view).
 73→    ///
 74→    /// This is a convenience method that combines drop + create operations.
 75→    async fn execute_model(
 76→        &self,
 77→        schema: &str,
 78→        name: &str,
 79→        sql: &str,
 80→        materialization: Materialization,
 81→        show_preview: bool,
 82→    ) -> Result<ExecutionResult, BackendError> {
 83→        let start = std::time::Instant::now();
 84→
 85→        match materialization {
 86→            Materialization::Table => {
 87→                self.drop_table_if_exists(schema, name).await?;
 88→                self.create_table_as(schema, name, sql).await?;
 89→            }
 90→            Materialization::View => {
 91→                self.drop_view_if_exists(schema, name).await?;
 92→                self.create_view_as(schema, name, sql).await?;
 93→            }
 94→        }
 95→
 96→        let duration = start.elapsed();
 97→        let row_count = self.get_row_count(schema, name).await?;
 98→
 99→        let preview = if show_preview {
100→            Some(self.get_preview(schema, name, 10).await?)
101→        } else {
102→            None
103→        };
104→
105→        Ok(ExecutionResult {
106→            model_name: name.to_string(),
107→            duration,
108→            row_count,
109→            preview,
110→        })
111→    }
112→
113→    /// Execute a model with incremental materialization support.
114→    ///
115→    /// Dispatches to the appropriate strategy (DELETE+INSERT, MERGE, APPEND, INSERT OVERWRITE).
116→    async fn execute_model_incremental(
117→        &self,
118→        schema: &str,
119→        name: &str,
120→        sql: &str,
121→        materialization: Materialization,
122→        strategy: MaterializationStrategy,
123→        show_preview: bool,
124→    ) -> Result<ExecutionResult, BackendError> {
125→        let start = std::time::Instant::now();
126→
127→        match (materialization, strategy) {
128→            (Materialization::View, _) => {
129→                self.drop_view_if_exists(schema, name).await?;
130→                self.create_view_as(schema, name, sql).await?;
131→            }
132→            (Materialization::Table, MaterializationStrategy::FullRefresh) => {
133→                self.drop_table_if_exists(schema, name).await?;
134→                self.create_table_as(schema, name, sql).await?;
135→            }
136→            (
137→                Materialization::Table,
138→                MaterializationStrategy::Incremental {
139→                    partition,
140→                    strategy: inc_strategy,
141→                    unique_key,
142→                },
143→            ) => {
144→                let table_exists = self.table_exists(schema, name).await?;
145→
146→                if !table_exists {
147→                    self.create_table_as(schema, name, sql).await?;
148→                } else {
149→                    match inc_strategy {
150→                        IncrementalStrategy::DeleteInsert => {
151→                            self.delete_partitions(schema, name, &partition).await?;
152→                            self.insert_into_from_query(schema, name, sql).await?;
153→                        }
154→                        IncrementalStrategy::Merge => {
155→                            self.merge_into(schema, name, sql, &unique_key).await?;
156→                        }
157→                        IncrementalStrategy::Append => {
158→                            self.insert_into_from_query(schema, name, sql).await?;
159→                        }
160→                        IncrementalStrategy::InsertOverwrite => {
161→                            self.insert_overwrite(schema, name, sql, &partition).await?;
162→                        }
163→                    }
164→                }
165→            }
166→        }
167→
168→        let duration = start.elapsed();
169→        let row_count = self.get_row_count(schema, name).await?;
170→
171→        let preview = if show_preview {
172→            Some(self.get_preview(schema, name, 10).await?)
173→        } else {
174→            None
175→        };
176→
177→        Ok(ExecutionResult {
178→            model_name: name.to_string(),
179→            duration,
180→            row_count,
181→            preview,
182→        })
183→    }
184→
185→    /// Resolve the best incremental strategy for the given config.
186→    ///
187→    /// Default implementation: uses MERGE if unique_key is set and supported,
188→    /// otherwise falls back to DELETE+INSERT.
189→    fn resolve_strategy(&self, config: &IncrementalConfig) -> IncrementalStrategy {
190→        if !config.unique_key.is_empty() && self.capabilities().supports_merge {
191→            IncrementalStrategy::Merge
192→        } else {
193→            IncrementalStrategy::DeleteInsert
194→        }
195→    }
196→
197→    /// Delete rows matching partition values.
198→    async fn delete_partitions(
199→        &self,
200→        schema: &str,
201→        name: &str,
202→        partition: &PartitionSpec,
203→    ) -> Result<(), BackendError>;
204→
205→    /// Insert data from a SELECT query into an existing table.
206→    async fn insert_into_from_query(
207→        &self,
208→        schema: &str,
209→        name: &str,
210→        sql: &str,
211→    ) -> Result<(), BackendError>;
212→
213→    /// MERGE (upsert) rows using unique_key columns for matching.
214→    ///
215→    /// Matched rows are updated, unmatched rows are inserted.
216→    async fn merge_into(
217→        &self,
218→        schema: &str,
219→        table: &str,
220→        source_sql: &str,
221→        unique_key: &[String],
222→    ) -> Result<(), BackendError>;
223→
224→    /// Replace partitions by inserting new data and removing old partition rows.
225→    ///
226→    /// Backends with native INSERT OVERWRITE use that; others emulate via
227→    /// DELETE (partition values derived from source) + INSERT.
228→    async fn insert_overwrite(
229→        &self,
230→        schema: &str,
231→        table: &str,
232→        sql: &str,
233→        partition: &PartitionSpec,
234→    ) -> Result<(), BackendError>;
235→}
