  1→//! Temporal window computation for incremental execution.
  2→//!
  3→//! Integrates AST-based temporal dependency analysis with upstream data latency
  4→//! to compute the effective filter window for incremental model execution.
  5→
  6→use smelt_core::{DataLatency, Granularity, IncrementalConfig, SourcesConfig};
  7→use smelt_optimizer::{
  8→    analyze_temporal_dependencies, compute_effective_window, granularity_period_days,
  9→    EffectiveWindow,
 10→};
 11→
 12→use crate::transformer::TimeRange;
 13→
 14→/// The result of computing temporal windows for an incremental model.
 15→#[derive(Debug, Clone)]
 16→pub struct IncrementalWindows {
 17→    /// The filter range — wider than requested to capture context rows.
 18→    /// Used for inject_time_filter() WHERE clause.
 19→    pub filter_range: TimeRange,
 20→    /// The partition range — the originally requested range.
 21→    /// Used for partition DELETE/overwrite.
 22→    pub partition_range: TimeRange,
 23→    /// The computed effective window (for explain output).
 24→    pub effective_window: EffectiveWindow,
 25→}
 26→
 27→/// Compute the incremental windows for a model.
 28→///
 29→/// Analyzes the SQL for temporal dependencies and resolves data latency
 30→/// from sources config and model metadata to determine the effective window.
 31→///
 32→/// Returns wider filter range and original partition range.
 33→pub fn compute_incremental_windows(
 34→    sql: &str,
 35→    config: &IncrementalConfig,
 36→    sources: Option<&SourcesConfig>,
 37→    model_metadata_latency: Option<&DataLatency>,
 38→    requested_range: &TimeRange,
 39→) -> IncrementalWindows {
 40→    // 1. Analyze SQL for temporal dependencies
 41→    let temporal_dep = analyze_temporal_dependencies(sql);
 42→
 43→    // 2. Resolve data latency
 44→    let data_latency_days =
 45→        resolve_data_latency(&config.event_time_column, sources, model_metadata_latency);
 46→
 47→    // 3. Compute effective window
 48→    let period_days = granularity_period_days(&config.granularity);
 49→    let effective_window = compute_effective_window(&temporal_dep, data_latency_days, period_days);
 50→
 51→    // 4. Compute filter range by adjusting the requested range
 52→    let filter_range = if effective_window.is_unbounded {
 53→        // Unbounded: can't widen meaningfully; the safety check should have caught this.
 54→        // Use the original range and let the safety override handle it.
 55→        requested_range.clone()
 56→    } else {
 57→        adjust_range(
 58→            requested_range,
 59→            effective_window.lookback_days,
 60→            effective_window.lookahead_days,
 61→            &config.granularity,
 62→        )
 63→    };
 64→
 65→    IncrementalWindows {
 66→        filter_range,
 67→        partition_range: requested_range.clone(),
 68→        effective_window,
 69→    }
 70→}
 71→
 72→/// Resolve data latency for an event_time_column.
 73→///
 74→/// Checks model metadata first (explicit declaration), then falls back to
 75→/// source definitions. Returns 0 if no latency information found.
 76→fn resolve_data_latency(
 77→    event_time_column: &str,
 78→    sources: Option<&SourcesConfig>,
 79→    model_metadata_latency: Option<&DataLatency>,
 80→) -> u32 {
 81→    // Model metadata latency takes priority
 82→    if let Some(latency) = model_metadata_latency {
 83→        return latency.to_days();
 84→    }
 85→
 86→    // Search sources for a column matching event_time_column
 87→    if let Some(sources_config) = sources {
 88→        for source in &sources_config.sources {
 89→            for table in &source.tables {
 90→                for col in &table.columns {
 91→                    if col.name == event_time_column {
 92→                        if let Some(ref latency) = col.data_latency {
 93→                            return latency.to_days();
 94→                        }
 95→                    }
 96→                }
 97→            }
 98→        }
 99→    }
100→
101→    0 // No latency information
102→}
103→
104→/// Adjust a time range by subtracting lookback days and adding lookahead days.
105→fn adjust_range(
106→    range: &TimeRange,
107→    lookback_days: u32,
108→    lookahead_days: u32,
109→    _granularity: &Granularity,
110→) -> TimeRange {
111→    if lookback_days == 0 && lookahead_days == 0 {
112→        return range.clone();
113→    }
114→
115→    use chrono::{Duration, NaiveDate};
116→
117→    let start = NaiveDate::parse_from_str(&range.start, "%Y-%m-%d")
118→        .unwrap_or_else(|_| NaiveDate::from_ymd_opt(2000, 1, 1).unwrap());
119→    let end = NaiveDate::parse_from_str(&range.end, "%Y-%m-%d")
120→        .unwrap_or_else(|_| NaiveDate::from_ymd_opt(2099, 12, 31).unwrap());
121→
122→    let adjusted_start = start - Duration::days(lookback_days as i64);
123→    let adjusted_end = end + Duration::days(lookahead_days as i64);
124→
125→    TimeRange {
126→        start: adjusted_start.format("%Y-%m-%d").to_string(),
127→        end: adjusted_end.format("%Y-%m-%d").to_string(),
128→    }
129→}
130→
131→#[cfg(test)]
132→mod tests {
133→    use super::*;
134→
135→    #[test]
136→    fn test_adjust_range_no_offset() {
137→        let range = TimeRange {
138→            start: "2026-03-20".into(),
139→            end: "2026-03-22".into(),
140→        };
141→        let result = adjust_range(&range, 0, 0, &Granularity::Day);
142→        assert_eq!(result.start, "2026-03-20");
143→        assert_eq!(result.end, "2026-03-22");
144→    }
145→
146→    #[test]
147→    fn test_adjust_range_lookback() {
148→        let range = TimeRange {
149→            start: "2026-03-20".into(),
150→            end: "2026-03-22".into(),
151→        };
152→        let result = adjust_range(&range, 6, 0, &Granularity::Day);
153→        assert_eq!(result.start, "2026-03-14");
154→        assert_eq!(result.end, "2026-03-22");
155→    }
156→
157→    #[test]
158→    fn test_adjust_range_lookahead() {
159→        let range = TimeRange {
160→            start: "2026-03-20".into(),
161→            end: "2026-03-22".into(),
162→        };
163→        let result = adjust_range(&range, 0, 1, &Granularity::Day);
164→        assert_eq!(result.start, "2026-03-20");
165→        assert_eq!(result.end, "2026-03-23");
166→    }
167→
168→    #[test]
169→    fn test_adjust_range_both() {
170→        let range = TimeRange {
171→            start: "2026-03-20".into(),
172→            end: "2026-03-22".into(),
173→        };
174→        let result = adjust_range(&range, 6, 1, &Granularity::Day);
175→        assert_eq!(result.start, "2026-03-14");
176→        assert_eq!(result.end, "2026-03-23");
177→    }
178→
179→    #[test]
180→    fn test_compute_windows_simple_group_by() {
181→        let sql = "SELECT date_trunc('day', event_time) as d, SUM(amount) FROM events GROUP BY 1";
182→        let config = IncrementalConfig {
183→            enabled: true,
184→            event_time_column: "event_time".into(),
185→            partition_column: "d".into(),
186→            granularity: Granularity::Day,
187→            unique_key: vec![],
188→            safety_overrides: Default::default(),
189→        };
190→        let range = TimeRange {
191→            start: "2026-03-20".into(),
192→            end: "2026-03-22".into(),
193→        };
194→
195→        let windows = compute_incremental_windows(sql, &config, None, None, &range);
196→
197→        // No temporal dependency, no latency → filter range = partition range
198→        assert_eq!(windows.filter_range.start, "2026-03-20");
199→        assert_eq!(windows.filter_range.end, "2026-03-22");
200→        assert_eq!(windows.partition_range.start, "2026-03-20");
201→        assert_eq!(windows.partition_range.end, "2026-03-22");
202→    }
203→
204→    #[test]
205→    fn test_compute_windows_with_lag() {
206→        let sql = "SELECT user_id, day, LAG(amount, 3) OVER (ORDER BY day) as prev FROM events";
207→        let config = IncrementalConfig {
208→            enabled: true,
209→            event_time_column: "event_time".into(),
210→            partition_column: "day".into(),
211→            granularity: Granularity::Day,
212→            unique_key: vec![],
213→            safety_overrides: Default::default(),
214→        };
215→        let range = TimeRange {
216→            start: "2026-03-20".into(),
217→            end: "2026-03-22".into(),
218→        };
219→
220→        let windows = compute_incremental_windows(sql, &config, None, None, &range);
221→
222→        // LAG(col, 3) → 3 periods lookback → filter starts 3 days earlier
223→        assert_eq!(windows.filter_range.start, "2026-03-17");
224→        assert_eq!(windows.filter_range.end, "2026-03-22");
225→        // Partition range stays the same
226→        assert_eq!(windows.partition_range.start, "2026-03-20");
227→        assert_eq!(windows.partition_range.end, "2026-03-22");
228→    }
229→
230→    #[test]
231→    fn test_compute_windows_with_data_latency() {
232→        let sql = "SELECT date_trunc('day', event_time) as d, SUM(amount) FROM events GROUP BY 1";
233→        let config = IncrementalConfig {
234→            enabled: true,
235→            event_time_column: "event_time".into(),
236→            partition_column: "d".into(),
237→            granularity: Granularity::Day,
238→            unique_key: vec![],
239→            safety_overrides: Default::default(),
240→        };
241→        let range = TimeRange {
242→            start: "2026-03-20".into(),
243→            end: "2026-03-22".into(),
244→        };
245→        let latency = DataLatency::parse("3 days").unwrap();
246→
247→        let windows = compute_incremental_windows(sql, &config, None, Some(&latency), &range);
248→
249→        // No temporal dep, but 3-day latency → filter starts 3 days earlier
250→        assert_eq!(windows.filter_range.start, "2026-03-17");
251→        assert_eq!(windows.filter_range.end, "2026-03-22");
252→        assert_eq!(windows.partition_range.start, "2026-03-20");
253→    }
254→}
255→

