use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

/// Persisted schema for a deployed model.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DeployedSchema {
    pub model: String,
    pub version: u32,
    pub deployed_at: DateTime<Utc>,
    pub model_hash: String,
    pub columns: Vec<DeployedColumn>,
}

/// A column in a deployed schema.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DeployedColumn {
    pub name: String,
    /// SQL type string (e.g., "INTEGER", "VARCHAR", "DECIMAL(10,2)")
    #[serde(rename = "type")]
    pub data_type: String,
    pub nullable: bool,
}

/// What kind of schema change was detected.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SchemaChange {
    AddColumn {
        name: String,
        data_type: String,
        nullable: bool,
    },
    RemoveColumn {
        name: String,
    },
    ChangeType {
        name: String,
        from: String,
        to: String,
    },
    ChangeNullability {
        name: String,
        from_nullable: bool,
        to_nullable: bool,
    },
}

/// Result of comparing deployed schema to inferred schema.
#[derive(Debug, Clone)]
pub struct SchemaDiff {
    pub changes: Vec<SchemaChange>,
}

impl SchemaDiff {
    /// No schema changes detected.
    pub fn is_empty(&self) -> bool {
        self.changes.is_empty()
    }

